      "ar": "وَلَيَحْمِلُنَّ أَثْقَالَهُمْ وَأَثْقَالًا مَّعَ أَثْقَالِهِمْ وَلَيُسْـءَلُنَّ يَوْمَ الْقِيَٰمَةِ عَمَّا كَانُواْ يَفْتَرُونَ",
