      "ar": "يَسْتَعْجِلُونَكَ بِالْعَذَابِ وَإِنَّ جَهَنَّمَ لَمُحِيطَةٌ بِالْكَٰفِرِينَ",
      "translit": "Yastaʿjilūnaka bil-ʿadhābi waʾinna jahannama lamuḥīṭatu bil-kāfirīn",
